using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Web.Script.Serialization;
public partial class TV {
 string latestUndoFile=null;bool cancelRequested=false;bool cancellableTask=false;
 void CheckCancelled(){if(cancelRequested)throw new OperationCanceledException("已取消；已完成的结果保留，未开始的操作不会执行。");}
 void CancelTask(){if(!busy){Report("当前没有运行中的任务。");return;}if(!cancellableTask){Report("当前操作正在提交，请等待完成；扫描和 AI 分析支持取消。");return;}cancelRequested=true;Report("正在取消，等待当前应用或请求返回后停止；已完成的结果会保留。");}
 public class UndoItem{public string Id,State,Result;public bool Done;}
 public class UndoBatch{public string Serial,Date,Mode,Device;public List<UndoItem> Items;}
 void BeginUndoBatch(List<Package> rows,string mode){if(mode=="restore")return;var b=new UndoBatch{Serial=serial,Device=status==null?serial:status.Text,Date=DateTime.Now.ToString("s"),Mode=mode,Items=rows.Select(p=>new UndoItem{Id=p.Id,State=p.State,Result="待执行"}).ToList()};latestUndoFile=DeviceDir+"/undo-"+DateTime.UtcNow.Ticks+".json";File.WriteAllText(latestUndoFile,new JavaScriptSerializer().Serialize(b));}
 void UpdateUndoResult(string id,string result){if(latestUndoFile==null||!File.Exists(latestUndoFile))return;var j=new JavaScriptSerializer();var b=j.Deserialize<UndoBatch>(File.ReadAllText(latestUndoFile));if(b.Serial!=serial)return;var row=b.Items.FirstOrDefault(x=>x.Id==id);if(row!=null){row.Result=result;File.WriteAllText(latestUndoFile,j.Serialize(b));}}
 void UndoRecent(){if(serial=="")throw new Exception("请先连接要恢复的电视");var file=Directory.GetFiles(DeviceDir,"undo-*.json").OrderByDescending(x=>x).FirstOrDefault(x=>!x.EndsWith(".done.json"));if(file==null)throw new Exception("本设备没有可撤销的操作批次");var b=new JavaScriptSerializer().Deserialize<UndoBatch>(File.ReadAllText(file));if(b.Serial!=serial)throw new Exception("恢复记录与当前电视不匹配");if(!Confirm("尝试撤销 "+b.Date+" 的 "+b.Mode+" 操作？\n电视："+serial+"\n"+string.Join("\n",b.Items.Select(x=>x.Id))+"\n第三方应用缺少 APK 时可能需要从备份恢复；不保证恢复应用数据。"))return;Run(async()=>{foreach(var item in b.Items.Where(x=>!x.Done)){try{if(!System.Text.RegularExpressions.Regex.IsMatch(item.Id,@"^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$"))throw new Exception("记录包名无效");if(item.State=="已安装")item.Result=await RestorePackage(item.Id);else if(item.State=="已停用"){await RestorePackage(item.Id);item.Result=await Shell("pm disable-user --user 0 "+item.Id);}else{item.Done=true;item.Result="操作前已卸载，不做破坏性回退";}if(!item.Done){string active=await Shell("pm list packages --user 0 "+item.Id),disabled=await Shell("pm list packages -d --user 0 "+item.Id);bool exists=active.Split('\n').Any(s=>s.Trim()=="package:"+item.Id),off=disabled.Split('\n').Any(s=>s.Trim()=="package:"+item.Id);if(!exists||(item.State=="已停用")!=off)throw new Exception("恢复状态未验证，请从 APK 备份恢复或手动检查");item.Done=true;}Report(item.Id+"："+item.Result);}catch(Exception ex){item.Result=ex.Message;Report(item.Id+"：恢复失败，"+ex.Message);}File.WriteAllText(file,new JavaScriptSerializer().Serialize(b));}if(b.Items.All(x=>x.Done))File.Move(file,file.Replace(".json",".done.json"));await Scan();});}
 public static string PairAddress(string value){if(!System.Text.RegularExpressions.Regex.IsMatch(value??"",@"^[A-Za-z0-9._-]+:[0-9]{1,5}$"))throw new Exception("请输入电视配对页面显示的 IP:配对端口");int port=int.Parse(value.Substring(value.LastIndexOf(':')+1));if(port<1||port>65535)throw new Exception("端口无效");return value;}
 void PairWireless(){if(busy)throw new Exception("请等待当前任务完成");string address=Prompt("电视 → 开发者选项 → 无线调试 → 使用配对码配对设备。\n输入该页面的 IP:配对端口（不是连接端口）","");if(address==null)return;PairAddress(address);string code=Prompt("输入电视显示的六位配对码","");if(code==null)return;if(!System.Text.RegularExpressions.Regex.IsMatch(code,@"^\d{6}$"))throw new Exception("配对码应为六位数字");Run(async()=>{string result=await Adb("pair "+Q(address)+" "+code,false);if(result.IndexOf("Successfully paired",StringComparison.OrdinalIgnoreCase)<0)throw new Exception("配对未完成，请检查配对码、端口和网络后重试。");Report("无线调试配对成功。请使用无线调试主页面的连接端口连接电视。");});}
 void RememberDevice(){if(serial=="")return;string file=Data+"/recent-devices.txt";var list=File.Exists(file)?File.ReadAllLines(file).ToList():new List<string>();list.RemoveAll(s=>s==serial);list.Insert(0,serial);File.WriteAllLines(file,list.Take(8));}
 void RecentDevices(){var file=Data+"/recent-devices.txt";var list=File.Exists(file)?File.ReadAllLines(file):new string[0];if(list.Length==0)throw new Exception("尚无连接记录");var w=new System.Windows.Window{Title="最近连接的电视",Owner=this,Width=500,Height=220,WindowStartupLocation=System.Windows.WindowStartupLocation.CenterOwner};var panel=new System.Windows.Controls.StackPanel{Margin=new System.Windows.Thickness(20)};ApplyMacChrome(w,panel);var choices=new System.Windows.Controls.ComboBox{ItemsSource=list,SelectedIndex=0,Margin=new System.Windows.Thickness(0,15,0,15)};panel.Children.Add(choices);Add(panel,"连接所选电视",()=>w.DialogResult=true);if(w.ShowDialog()!=true)return;host.Text=(string)choices.SelectedItem;Connect();}
}
